// Node: Montar aviso de erro  (Code, "Run Once for All Items")
// Recebe o erro de qualquer execução do GasBot e monta o e-mail.
// Para não lotar sua caixa, o mesmo erro no mesmo nó só avisa 1 vez a cada 10 minutos.

const e = $input.first().json;

const fluxo = (e.workflow && e.workflow.name) || "workflow";
const no = (e.execution && e.execution.lastNodeExecuted) || "desconhecido";
const mensagem = (e.execution && e.execution.error && e.execution.error.message) || "sem mensagem";
const link = (e.execution && e.execution.url) || "";
const idExecucao = (e.execution && e.execution.id) || "";

const sd = $getWorkflowStaticData("global");
sd.erros = sd.erros || {};

const chave = `${fluxo}|${no}`;
const agora = Date.now();

if (sd.erros[chave] && agora - sd.erros[chave] < 10 * 60000) {
  return [];
}

sd.erros[chave] = agora;

const hora = new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" });

return [{
  json: {
    assunto: `[GasBot] ERRO no nó "${no}"`,
    texto:
      `Erro em ${hora}\n\n` +
      `Fluxo: ${fluxo}\n` +
      `Nó que falhou: ${no}\n` +
      `Mensagem: ${mensagem}\n` +
      (idExecucao ? `Execução: #${idExecucao}\n` : "") +
      (link ? `Abrir: ${link}\n` : "") +
      `\nO cliente pode ter ficado sem resposta. Abra a execução no n8n (aba Executions) para ver o que aconteceu.`
  }
}];
